package main

import (
 "io"
 "log"
 "net/http"
 "os"
)

func main() {
 p := os.Getenv("PORT")
 if p == "" { p = "10000" }
 http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
  w.Header().Set("Content-Type", "text/html; charset=utf-8")
  io.WriteString(w, html)
 })
 log.Println("Running on :" + p)
 log.Fatal(http.ListenAndServe(":"+p, nil))
}

const html = "<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>Uwashusema</title><script src='https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js'></script><style>body{margin:0;font-family:system-ui;background:#f1f5f1}header{background:#1a6d2f;color:#fff;padding:14px;text-align:center;font-weight:900}.card{background:#fff;margin:8px;border-radius:10px;padding:10px}select,input,button{width:100%;padding:10px;margin:4px 0;border-radius:6px;border:1px solid #bbb}button{background:#1a6d2f;color:#fff;font-weight:900;border:0}.blue{background:#1565c0}</style><header>Uwashusema Mahida</header><div class=card><select id=m><option value=1>Jan<option value=2>Feb<option value=3>Mar<option value=4>Apr<option value=5>Mei<option value=6>Jun<option value=7>Jul<option value=8>Ago<option value=9>Sep<option value=10>Okt<option value=11>Nov<option value=12>Des</select><input id=y type=number value=2026><button onclick=render()>Sawa</button></div><div class=card><h3>Wanachama <button onclick=addW() style=width:auto>+ Mpya</button></h3><div id=wl></div></div><div class=card><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada 20k<option value=marejesho>Marejesho<option value=faini_ada>Riba 30% ya Ada<option value=faini_marejesho>Riba 30% ya Rejesho<option value=michango>Michango<option value=mkopo_toka>Mkopo kwa Mwanachama</select><input id=k type=number placeholder='Kiasi'><input id=ma placeholder=Maelezo><button onclick=addM()>Hifadhi</button><div id=ca style=color:#1a6d2f;font-weight:800></div></div><div class=card><button class='blue' onclick=doExcel()>Pakua Excel</button><div id=mu></div><div id=hi></div></div><script>var D=JSON.parse(localStorage.getItem('f')||'null')||{w:[{j:'Charles Joseph Mgaya'}],m:[]};function curM(){return +m.value}function curY(){return +y.value||2026}function save(){localStorage.setItem('f',JSON.stringify(D));render()}function addW(){var j=prompt('Jina:');if(!j)return;D.w.push({j:j});save()}var kEl=document.getElementById('k');sa.addEventListener('change',function(){var k=+kEl.value;if(sa.value=='mkopo_toka'&&k>0)ca.innerHTML='Fomu 5% AUTO = '+(Math.round(k*0.05)).toLocaleString()+' | 1.5M = 75k';else ca.innerHTML=''});kEl.addEventListener('input',function(){sa.dispatchEvent(new Event('change'))});function addM(){var w=sw.value,a=sa.value,k=+kEl.value,ma=maEl.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,ma:ma,mm:curM(),yy:curY(),t:new Date().toLocaleString()});if(a=='mkopo_toka'){var f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,ma:'Fomu 5% AUTO',mm:curM(),yy:curY(),t:'AUTO'})}kEl.value='';maEl.value='';ca.innerHTML='';save()}var maEl=document.getElementById('ma');function render(){var mm=curM(),yy=curY();var mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);wl.innerHTML='';sw.innerHTML='';D.w.forEach((x,i)=>{wl.innerHTML+='<div>'+x.j+' <button onclick=\"D.w.splice('+i+',1);save()\">X</button></div>';sw.innerHTML+='<option>'+x.j+'</option>'});mu.innerHTML='';var s={};mi.forEach(t=>{s[t.a]=(s[t.a]||0)+t.k});for(var k in s){mu.innerHTML+=k+':'+s[k].toLocaleString()+'<br>'}hi.innerHTML='';mi.slice().reverse().forEach(t=>{hi.innerHTML+='<div>'+t.w+'-'+t.a+'-'+t.k.toLocaleString()+'</div>'})}function doExcel(){var mm=curM(),yy=curY();var all=D.m.filter(x=>x.mm==mm&&x.yy==yy);var a1=[['Jina','Ada 20k','Riba 30% Ada']],a2=[['Jina','Mkopo','Fomu 5% 75k','Marejesho','Riba 30% Rejesho']],a3=[['Jina','Hisa Mwezi','Jumla Hisa']];var am={},dm={},hm={},ht={};D.w.forEach(x=>{am[x.j]=0;dm[x.j]={c:0,f:0,r:0,fr:0};hm[x.j]=0;ht[x.j]=0});all.forEach(t=>{if(t.a=='ada')am[t.w]+=t.k;if(t.a=='faini_ada')am[t.w+'_r']=(am[t.w+'_r']||0)+t.k;if(t.a=='mkopo_toka')dm[t.w].c+=t.k;if(t.a=='fomu')dm[t.w].f+=t.k;if(t.a=='marejesho')dm[t.w].r+=t.k;if(t.a=='faini_marejesho')dm[t.w].fr+=t.k;if(t.a=='hisa')hm[t.w]+=t.k});D.m.forEach(t=>{if(t.a=='hisa')ht[t.w]=(ht[t.w]||0)+t.k});for(var j in am){if(!j.includes('_r'))a1.push([j,am[j],am[j+'_r']||0])}for(var j in dm){if(dm[j].c>0||dm[j].f>0)a2.push([j,dm[j].c,dm[j].f,dm[j].r,dm[j].fr])}for(var j in hm){a3.push([j,hm[j],ht[j]||0])}var wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a1),'1-Ada');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a2),'2-Mikopo');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(a3),'4-Hisa');XLSX.writeFile(wb,'Uwashusema.xlsx')}m.value=new Date().getMonth()+1;render();</script>"
